//! 🛬️ Direct Flow native binding with typed partial owners and cumulative controls.
use super::*;
use semio_framework_dsl_record::DslField;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::RecordValue;
use semio_framework_dsl_record::__rt::DecodedFieldOwner;
use semio_framework_value::{FromValue,NativeDecodeControl,ValueError,ValueRefusalKind};
use neural::{ColdDictionaryBuilder,ColdOwner};
use std::mem::size_of;
use std::sync::Arc;
type Result<T>=std::result::Result<T,ValueError>;
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn field<'a>(record:&'a RecordValue,id:u16)->&'a FieldValue{record.get(id).unwrap_or(&semio_framework_dsl_record::FieldValue::Absent)}
fn read<T:DslField>(record:&RecordValue,id:u16,control:&mut NativeDecodeControl<'_>)->Result<T>{control.scoped_stage(|control|{control.begin_stage(0)?;T::from_value_controlled(field(record,id),control)})}
fn block(value:&FieldValue)->Result<&FieldValue>{match value{semio_framework_dsl_record::FieldValue::Block(value)=>Ok(value),_=>Err(invalid("Flow declared native block is required"))}}
fn record(value:&FieldValue)->Result<&RecordValue>{match value{semio_framework_dsl_record::FieldValue::Record(value)=>Ok(value),_=>Err(invalid("Flow declared native record is required"))}}
fn list(value:&FieldValue)->Result<&[FieldValue]>{match value{semio_framework_dsl_record::FieldValue::List(values)=>Ok(values),_=>Err(invalid("Flow declared native list is required"))}}
fn statements(value:&FieldValue)->Result<&[(String,RecordValue)]>{match value{semio_framework_dsl_record::FieldValue::Statements(values)=>Ok(values),_=>Err(invalid("Flow declared native statements are required"))}}
fn retire_map<V:FromValue>(map:crate::OrderedMap<V>){use semio_framework_value::ordered::{Grant,RetirementStep};let mut retirement=map.retire();loop{let maximum_bytes=retirement.next_close_byte_demand().expect("Flow native ordered cold demand").max(1);match retirement.advance(Grant{maximum_items:1,maximum_bytes}){RetirementStep::OwnedValue(value)=>V::retire_decoded(value),RetirementStep::Complete=>break,_=>{}}}}
fn insert<V:FromValue>(map:&mut crate::OrderedMap<V>,key:String,value:V,control:&mut NativeDecodeControl<'_>)->Result<()>{use semio_framework_value::ordered::{Grant,RetirementStep};let value=semio_framework_value::DecodedValue::new(value,V::retire_decoded);control.charge(size_of::<String>()+size_of::<V>()+4*size_of::<usize>())?;let mut update=map.begin_set(key,value.take());let grant=Grant{maximum_items:1,maximum_bytes:4096};let result=(||{while !update.is_complete(){update.advance_insert_controlled(grant,control)?;}let replacement=update.take_result().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"Flow native ordered result missing"))?;if let Some(value)=update.take_removed(){if let Some(value)=Arc::into_inner(value){V::retire_decoded(value);}retire_map(replacement);return Err(invalid("Flow native ordered key repeated"))}retire_map(std::mem::replace(map,replacement));Ok(())})();update.begin_close();loop{match update.close_step(grant){RetirementStep::OwnedValue(value)=>V::retire_decoded(value),RetirementStep::Complete=>break,_=>{}}}result}
fn dictionary(value:&FieldValue,control:&mut NativeDecodeControl<'_>)->Result<Dictionary>{control.scoped_depth(64,|control|control.scoped_stage(|control|{let entries=match value{semio_framework_dsl_record::FieldValue::Absent=>return Ok(Dictionary::new()),semio_framework_dsl_record::FieldValue::Map(entries)=>entries,_=>return Err(invalid("Flow native neural dictionary map required"))};control.begin_stage(entries.len())?;let mut builder=ColdDictionaryBuilder::new();for(key,value)in entries{let key=control.copy_text(key)?;let value=neural_value(record(value)?,control)?;builder.insert_controlled(key,value,control)?;control.step()?;}Ok(builder.finish())}))}
fn neural_value(value:&RecordValue,control:&mut NativeDecodeControl<'_>)->Result<NeuralValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let mut active=None;for id in 0..6{control.step()?;if !matches!(field(value,id),FieldValue::Absent){if active.replace(id).is_some(){return Err(invalid("Flow native neural value has multiple variants"))}}}match active{
 Some(0)=>{let _:bool=read(value,0,control)?;Ok(NeuralValue::Atom(Atom::Null))},
 Some(1)=>Ok(NeuralValue::Atom(Atom::Boolean(read(value,1,control)?))),
 Some(2)=>Ok(NeuralValue::Atom(Atom::Integer(read(value,2,control)?))),
 Some(3)=>Ok(NeuralValue::Atom(Atom::Decimal(read(value,3,control)?))),
 Some(4)=>Ok(NeuralValue::Atom(Atom::String(read(value,4,control)?))),
 Some(5)=>dictionary(field(value,5),control).map(NeuralValue::Dictionary),
 _=>Err(invalid("Flow native neural value variant missing")),
}}))}
fn wire(value:&RecordValue,control:&mut NativeDecodeControl<'_>)->Result<SynapseSpec>{let semio_framework_dsl_record::FieldValue::Wire(wire)=field(value,1)else{return Err(invalid("Flow native synapse wire required"))};let Some((true,to))=&wire.edge else{return Err(invalid("Flow native synapse directed target required"))};Ok(SynapseSpec{id:read(value,0,control)?,from:control.copy_text(&wire.from.id)?,to:control.copy_text(&to.id)?,from_port:match &wire.from.port{Some(value)=>control.copy_text(value)?,None=>String::new()},to_port:match &to.port{Some(value)=>control.copy_text(value)?,None=>String::new()}})}
fn tree(value:&RecordValue,control:&mut NativeDecodeControl<'_>)->Result<Tree>{control.scoped_depth(64,|control|control.scoped_stage(|control|{let entries=statements(block(field(value,0))?)?;control.begin_stage(0)?;let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Tree{neurons:control.allocate_vec(entries.len())?,synapses:control.allocate_vec(list(field(value,1))?.len())?},|value|FlowRetirement::from_owner(FlowOwner::Tree(value)).retire_cold());for(keyword,value)in entries{if keyword!="neuron"{return Err(invalid("Flow native neuron keyword differs"))}let id=read(value,0,control)?;let kind=read(value,1,control)?;let params=ColdOwner::new(dictionary(field(value,2),control)?);let child=match field(value,3){semio_framework_dsl_record::FieldValue::Absent=>None,value=>{let child=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(tree(record(block(value)?)?,control)?,|value|FlowRetirement::from_owner(FlowOwner::Tree(value)).retire_cold());control.charge(size_of::<Tree>())?;Some(Box::new(child.take()))}};output.as_mut().neurons.push(Neuron{id,kind,params:params.into_inner(),tree:child});control.step()?;}for value in list(field(value,1))?{let spec=wire(record(value)?,control)?;output.as_mut().synapses.push(Synapse{id:spec.id,from:spec.from,to:spec.to,from_port:spec.from_port,to_port:spec.to_port});control.step()?;}Ok(output.take())}))}
fn set(value:&FieldValue,control:&mut NativeDecodeControl<'_>)->Result<crate::OrderedSet>{let values=<Vec<String> as DslField>::from_value_controlled(value,control)?;let mut map=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(crate::OrderedMap::new(),retire_map::<()>);for key in values{insert(map.as_mut(),key,(),control)?;control.step()?;}Ok(crate::OrderedSet::from_map(map.take()))}
fn gui(value:&semio_framework_value::DslValue,control:&mut NativeDecodeControl<'_>)->Result<FlowGui>{control.scoped_depth(64,|control|control.scoped_stage(|control|{use semio_framework_value::DslValue;let semio_framework_value::DslValue::Object(_)=value else{return Err(invalid("Flow native GUI object required"))};let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(FlowGui{camera:<CameraJson as FromValue>::from_value_controlled(value.get("camera").ok_or_else(||invalid("Flow native GUI camera missing"))?,control)?,nodes:crate::OrderedMap::new(),previews:Vec::new()},|value|FlowRetirement::from_owner(FlowOwner::Gui(value)).retire_cold());if let Some(nodes)=value.get("nodes"){let semio_framework_value::DslValue::Object(nodes)=nodes else{return Err(invalid("Flow native GUI node object required"))};for(key,value)in nodes{let key=control.copy_text(key)?;let node=<FlowNodeGui as FromValue>::from_value_controlled(value,control)?;insert(&mut output.as_mut().nodes,key,node,control)?;control.step()?;}}
 if let Some(previews)=value.get("previews"){let semio_framework_value::DslValue::Array(previews)=previews else{return Err(invalid("Flow native GUI preview array required"))};output.as_mut().previews=control.allocate_vec(previews.len())?;for value in previews{let id=<String as FromValue>::from_value_controlled(value.get("id").ok_or_else(||invalid("Flow preview id missing"))?,control)?;let source=match value.get("source"){Some(value)=><Option<FlowChannelRef> as FromValue>::from_value_controlled(value,control)?,None=>None};let mode=<String as FromValue>::from_value_controlled(value.get("mode").ok_or_else(||invalid("Flow preview mode missing"))?,control)?;let preview=ColdOwner::new(match value.get("preview"){Some(value)=><Dictionary as FromValue>::from_value_controlled(value,control)?,None=>Dictionary::new()});let mut expanded=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(crate::OrderedMap::new(),retire_map::<()>);if let Some(paths)=value.get("expanded"){let semio_framework_value::DslValue::Array(paths)=paths else{return Err(invalid("Flow preview paths required"))};for path in paths{let key=<String as FromValue>::from_value_controlled(path,control)?;insert(expanded.as_mut(),key,(),control)?;}}let layout=match value.get("layout"){Some(value)=><Option<WidgetLayout> as FromValue>::from_value_controlled(value,control)?,None=>None};output.as_mut().previews.push(FlowPreviewGui{id,source,mode,preview:preview.into_inner(),expanded:crate::OrderedSet::from_map(expanded.take()),layout});control.step()?;}}
 Ok(output.take())}))}
fn widget(keyword:&str,value:&RecordValue,control:&mut NativeDecodeControl<'_>)->Result<Widget>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let id=read(value,0,control)?;Ok(match keyword{
 "neuron"=>{let neuron_kind=read(value,1,control)?;let params=ColdOwner::new(dictionary(field(value,2),control)?);let input_ports=read(value,3,control)?;let output_ports=read(value,4,control)?;let preview=read(value,5,control)?;Widget::Neuron{id,neuron_kind,params:params.into_inner(),input_ports,output_ports,preview}},
 "input-slider"=>Widget::InputSlider{id,label:read(value,1,control)?,value:read(value,2,control)?,min:read(value,3,control)?,max:read(value,4,control)?,step:read(value,5,control)?},
 "input-note"=>Widget::InputNote{id,text:read(value,1,control)?},
 "input-image"=>Widget::InputImage{id,src:read(value,1,control)?},
 "variable"=>Widget::Variable{id,name:read(value,1,control)?,schema:read(value,2,control)?},
 "output-preview"=>{let preview=ColdOwner::new(dictionary(field(value,1),control)?);let expanded=set(field(value,2),control)?;Widget::OutputPreview{id,preview:preview.into_inner(),expanded}},
 "output-action"=>Widget::OutputAction{id,action:read(value,1,control)?},
 "output-export"=>Widget::OutputExport{id,format:read(value,1,control)?},
 "cluster"=>{let name=read(value,1,control)?;let tree=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(tree(record(block(field(value,2))?)?,control)?,|value|FlowRetirement::from_owner(FlowOwner::Tree(value)).retire_cold());let semio_framework_dsl_record::FieldValue::Value(value)=field(value,3)else{return Err(invalid("Flow native GUI intrinsic value required"))};let flow=gui(value,control)?;Widget::Cluster{id,name,tree:tree.take(),flow}},
 _=>return Err(invalid("Flow declared widget variant differs")),
})}))}
/// 🌊️ Binds actual persisted fields directly from a borrowed native record.
pub(super) fn decode_record(value:&RecordValue,control:&mut NativeDecodeControl<'_>)->Result<FlowHostSnapshot>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let widgets=statements(block(field(value,2))?)?;let synapses=list(field(value,3))?;let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(FlowHostSnapshot{schema:read(value,0,control)?,camera:CameraJson::__dsl_from_record_controlled(record(block(field(value,1))?)?,control)?,widgets:control.allocate_vec(widgets.len())?,synapses:control.allocate_vec(synapses.len())?,layout:crate::OrderedMap::new()},FlowHostSnapshot::retire_cold);for(keyword,value)in widgets{output.as_mut().widgets.push(widget(keyword,value,control)?);control.step()?;}for value in synapses{output.as_mut().synapses.push(wire(record(value)?,control)?);control.step()?;}let semio_framework_dsl_record::FieldValue::Map(layout)=field(value,4)else{return Err(invalid("Flow native layout map required"))};for(key,value)in layout{let key=control.copy_text(key)?;let layout=WidgetLayout::__dsl_from_record_controlled(record(value)?,control)?;insert(&mut output.as_mut().layout,key,layout,control)?;control.step()?;}Ok(output.take())}))}
